content:
Here is a complete, idiomatic Terraform refactoring that consolidates duplicated `dev`/`prod` blocks into a single parameterized module using `for_each`. The solution assumes AWS based on the resource types specified.

### 📁 Project Structure
```
terraform/
├── main.tf                  # Root: for_each module instantiation
├── variables.tf             # Root variables & env config map
└── modules/
    └── environment/
        ├── main.tf          # Reusable infrastructure definition
        └── variables.tf      # Module inputs
```

### 🧩 1. Root Configuration (`main.tf`)
Uses `for_each` to instantiate the module once per environment. Environment isolation is maintained by pairing this with separate Terraform workspaces or distinct state backends per environment.

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = ">= 5.0" }
    # sops = { source = "carvel/dev-secret.sops" } # Optional: native SOPS provider
  }
}

provider "aws" {
  region = var.aws_region
}

# Environment topology map
locals {
  env_configs = {
    dev = {
      region = "us-east-1"
      cluster = { node_count = 2, instance_type = "t3.medium" }
      s3      = { cross_region_replication = false, target_region = "" }
      rds     = { instance_class = "db.t3.micro", multi_az = false, encrypted = false }
      iam     = { programmatic = true, oidc_provider_arn = "" }
      https   = { use_cloudfront = false, internal = true, acm_cert_arn = "" }
    }
    prod = {
      region = "us-west-2"
      cluster = { node_count = 4, instance_type = "t3.large" }
      s3      = { cross_region_replication = true, target_region = "us-west-2" }
      rds     = { instance_class = "db.t3.medium", multi_az = true, encrypted = true }
      iam     = { programmatic = false, oidc_provider_arn = var.prod_oidc_provider_arn }
      https   = { use_cloudfront = true, internal = false, acm_cert_arn = var.prod_acm_cert_arn }
    }
  }
}

module "environments" {
  source = "./modules/environment"

  for_each = local.env_configs

  env_name     = each.key
  region       = each.value.region
  subnet_ids   = data.aws_subnets.available.ids # Assume data source provides env-specific subnets
  cluster      = each.value.cluster
  s3           = each.value.s3
  rds          = each.value.rds
  iam          = each.value.iam
  https        = each.value.https
  db_password  = var.db_passwords[each.key]     # SOPS-encrypted in tfvars
  kms_key_arn  = var.kms_key_arns[each.key]
}
```

### 📦 2. Reusable Module (`modules/environment/main.tf`)
All resources are defined once. Conditionals handle environment-specific differences. Sensitive values are never committed plaintext.

```hcl
# 🟦 EKS Cluster & Managed Node Group
resource "aws_eks_cluster" "main" {
  name     = "${var.env_name}-eks"
  role_arn = aws_iam_role.eks.arn
  version  = "1.28"

  vpc_config {
    subnet_ids         = var.subnet_ids
    security_group_ids = [aws_security_group.eks.arn]
  }
}

resource "aws_eks_node_group" "main" {
  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "${var.env_name}-workers"
  node_role_arn   = aws_iam_role.node.arn
  subnet_ids      = var.subnet_ids
  instance_types  = [var.cluster.instance_type]

  scaling_config {
    desired_size = var.cluster.node_count
    min_size     = 1
    max_size     = var.cluster.node_count
  }
}

# 🔐 IAM Roles & User
resource "aws_iam_role" "eks" {
  name = "${var.env_name}-eks-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "eks.amazonaws.com" }
      Action   = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role" "node" {
  name = "${var.env_name}-node-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action   = "sts:AssumeRole"
    }]
  })
}

# Prod: OIDC Trust Role (Least Privilege)
resource "aws_iam_role" "service_account" {
  count = var.iam.oidc_provider_arn != "" ? 1 : 0
  name  = "${var.env_name}-svc-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Federated = var.iam.oidc_provider_arn }
      Action   = "sts:AssumeRoleWithWebIdentity"
      Condition = { StringEquals = { "${var.env_name}-eks.eks.amazonaws.com/aud" = "sts.amazonaws.com" } }
    }]
  })
}

# Dev: Programmatic User
resource "aws_iam_user" "dev_access" {
  count = var.iam.programmatic ? 1 : 0
  name  = "${var.env_name}-app-user"
}

# 🪣 S3 Bucket (Assets)
resource "aws_s3_bucket" "assets" {
  bucket = "${var.env_name}-app-assets-${var.region}"
  tags   = { Environment = var.env_name }
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "AES256" }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-Region Replication (Prod Only)
resource "aws_iam_role" "s3_replication" {
  count = var.s3.cross_region_replication ? 1 : 0
  name  = "${var.env_name}-s3-replication-role"
  # Assume role policy & permissions omitted for brevity (standard replication policy)
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count  = var.s3.cross_region_replication ? 1 : 0
  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.s3_replication[count.index].arn

  rule {
    id     = "replication"
    status = "Enabled"
    destination {
      bucket = "${aws_s3_bucket.assets.id}-repl-${var.s3.target_region}"
      # target_account, encryption_config, etc.
    }
  }
}

# 🐘 RDS PostgreSQL
resource "aws_db_instance" "main" {
  identifier              = "${var.env_name}-postgres"
  engine                  = "postgres"
  engine_version          = "14.9"
  instance_class          = var.rds.instance_class
  allocated_storage       = 20
  db_name                 = "appdb"
  username                = "admin"
  password                = var.db_password
  publicly_accessible     = false
  skip_final_snapshot     = true
  deletion_protection     = true
  multi_az                = var.rds.multi_az
  storage_encrypted       = var.rds.encrypted
  kms_key_id              = var.rds.encrypted ? var.kms_key_arn : null
  backup_retention_period = 7
  vpc_security_group_ids  = [aws_security_group.rds.id]
  db_subnet_group_name    = "default"
}

# 🔒 Secret (DB Connection String)
resource "aws_secretsmanager_secret" "db_conn" {
  name       = "${var.env_name}-db-connection-string"
  kms_key_id = var.kms_key_arn
}

resource "aws_secretsmanager_secret_version" "db_conn" {
  secret_id     = aws_secretsmanager_secret.db_conn.id
  secret_string = jsonencode({
    uri = "postgres://${aws_db_instance.main.username}:${var.db_password}@${aws_db_instance.main.endpoint}/appdb"
  })
}

# 🌐 HTTPS Exposure (ALB vs CloudFront)
resource "aws_lb" "main" {
  count            = var.https.use_cloudfront ? 0 : 1
  name             = "${var.env_name}-alb"
  internal         = var.https.internal
  load_balancer_type = "application"
  security_groups  = [aws_security_group.alb.id]
  subnets          = var.subnet_ids
}

resource "aws_lb_listener" "https" {
  count            = var.https.use_cloudfront ? 0 : 1
  load_balancer_arn = aws_lb.main[count.index].arn
  port             = 443
  protocol         = "HTTPS"
  ssl_policy       = "ELBSecurityPolicy-TLS13-1-2021-06"
  certificate_arn  = var.https.acm_cert_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main[count.index].arn
    # No 80->443 redirect listener created per spec
  }
}

resource "aws_cloudfront_distribution" "main" {
  count = var.https.use_cloudfront ? 1 : 0
  origin {
    domain_name = aws_lb.main[0].dns_name
    origin_id   = "InternalALB"
    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }
  viewer_certificate {
    acm_certificate_arn = var.https.acm_cert_arn
    ssl_support_method  = "sni-only"
  }
  restrictions {
    geo_restriction { restriction_type = "none" }
  }
  # default_cache_behavior, price_class, etc.
}
```

